-- Начальные данные: справочники и 60 фильмов.
-- Постеров нет (poster_url = NULL), на сайте вместо них показывается заглушка.
-- Рейтинги указаны приблизительно, по шкале от 0 до 10.

INSERT INTO type (name) VALUES ('фильм'), ('сериал'), ('мультфильм');

INSERT INTO mood (name) VALUES
    ('весёлое'), ('уютное'), ('напряжённое'), ('грустное'), ('вдохновляющее'), ('мрачное');

INSERT INTO genre (name) VALUES
    ('драма'), ('комедия'), ('боевик'), ('триллер'), ('фантастика'), ('фэнтези'),
    ('ужасы'), ('мелодрама'), ('приключения'), ('детектив'), ('криминал'),
    ('семейный'), ('исторический'), ('военный'), ('биография'), ('мюзикл');

-- Фильмы. Тип указывается названием, а id подставляется через JOIN.
INSERT INTO movie (title, release_year, description, rating, type_id)
SELECT v.title, v.release_year, v.description, v.rating, t.id
FROM (VALUES
    -- Фильмы
    ('Побег из Шоушенка', 1994, 'Банкира Энди Дюфрейна несправедливо осуждают за убийство жены. Двадцать лет в тюрьме он сохраняет достоинство, заводит настоящую дружбу и терпеливо готовит свой путь к свободе.', 9.3, 'фильм'),
    ('Крёстный отец', 1972, 'История семьи Корлеоне, одной из самых влиятельных мафиозных семей Нью-Йорка. Младший сын, не собиравшийся связываться с семейным делом, постепенно становится его главой.', 9.2, 'фильм'),
    ('Тёмный рыцарь', 2008, 'Бэтмен вместе с полицией Готэма почти справился с организованной преступностью, но в городе появляется Джокер, который хочет посеять хаос и доказать, что любой человек может сломаться.', 9.0, 'фильм'),
    ('Форрест Гамп', 1994, 'Простодушный и добрый Форрест рассказывает историю своей жизни, в которой он случайно оказывается свидетелем и участником главных событий в истории США, но всё это время думает только о любимой девушке.', 8.8, 'фильм'),
    ('Начало', 2010, 'Кобб умеет проникать в чужие сны и красть идеи. Ему поручают обратное: незаметно внедрить мысль в сознание наследника крупной корпорации, для чего команде приходится погружаться в сон внутри сна.', 8.8, 'фильм'),
    ('Интерстеллар', 2014, 'Земля умирает от неурожаев, и бывший пилот отправляется через червоточину искать планету, пригодную для жизни. Время на корабле течёт иначе, а дома его ждёт дочь.', 8.7, 'фильм'),
    ('Матрица', 1999, 'Хакер Нео узнаёт, что привычный мир на самом деле компьютерная симуляция, созданная машинами. Он присоединяется к небольшой группе людей, которые борются за освобождение человечества.', 8.7, 'фильм'),
    ('Зелёная миля', 1999, 'Надзиратель блока смертников знакомится с осуждённым великаном Джоном Коффи, который обладает удивительным даром исцелять. Постепенно становится ясно, что этот тихий человек невиновен.', 8.6, 'фильм'),
    ('Бойцовский клуб', 1999, 'Офисный служащий страдает от бессонницы и пустоты жизни. Знакомство с дерзким Тайлером Дёрденом приводит к созданию подпольного клуба, который быстро выходит из-под контроля.', 8.8, 'фильм'),
    ('Криминальное чтиво', 1994, 'Несколько переплетённых историй из жизни лос-анджелесских бандитов: два киллера, боксёр, сдавший бой, жена босса и пара грабителей. События показаны вне хронологического порядка.', 8.9, 'фильм'),
    ('Список Шиндлера', 1993, 'Немецкий предприниматель Оскар Шиндлер во время Второй мировой войны нанимает на свою фабрику евреев и тем самым спасает более тысячи человек от гибели в концлагерях.', 9.0, 'фильм'),
    ('Властелин колец: Братство кольца', 2001, 'Хоббит Фродо получает в наследство кольцо Всевластья, которое нужно уничтожить в огне Роковой горы. Вместе с друзьями, магом, людьми, эльфом и гномом он отправляется в опасный путь.', 8.9, 'фильм'),
    ('Гладиатор', 2000, 'Римского полководца Максимуса предаёт новый император, а его семью убивают. Став рабом и гладиатором, он пробивается на арену Колизея, чтобы отомстить.', 8.5, 'фильм'),
    ('Молчание ягнят', 1991, 'Молодая курсантка ФБР ищет маньяка и за помощью обращается к заключённому психиатру-людоеду Ганнибалу Лектеру. Между ними начинается опасная психологическая игра.', 8.6, 'фильм'),
    ('Семь', 1995, 'Опытный детектив накануне пенсии и его молодой напарник расследуют серию убийств, каждое из которых связано с одним из семи смертных грехов.', 8.6, 'фильм'),
    ('Спасти рядового Райана', 1998, 'После высадки в Нормандии капитан с небольшим отрядом получает приказ найти рядового Райана, все братья которого погибли, и вернуть его домой.', 8.6, 'фильм'),
    ('1+1', 2011, 'Богатый аристократ, парализованный после несчастного случая, берёт в помощники парня из пригорода, который только что вышел из тюрьмы. Их необычная дружба меняет обоих.', 8.5, 'фильм'),
    ('Достучаться до небес', 1997, 'Двое смертельно больных парней сбегают из больницы на угнанной машине с чемоданом чужих денег, чтобы успеть увидеть море. За ними гонятся и бандиты, и полиция.', 7.9, 'фильм'),
    ('Амели', 2001, 'Застенчивая официантка с Монмартра решает тайно помогать окружающим и делать их жизнь чуть счастливее, но никак не решается устроить собственное счастье.', 8.3, 'фильм'),
    ('Один дома', 1990, 'Большая семья улетает на Рождество в Париж и забывает дома восьмилетнего Кевина. Мальчику приходится защищать дом от двух незадачливых грабителей.', 7.7, 'фильм'),
    ('Назад в будущее', 1985, 'Подросток Марти на машине времени, которую построил его друг-учёный, попадает в 1955 год и случайно мешает знакомству своих родителей. Теперь ему нужно всё исправить.', 8.5, 'фильм'),
    ('Титаник', 1997, 'На борту знаменитого лайнера бедный художник и девушка из высшего общества влюбляются друг в друга. Их роман прерывается катастрофой.', 7.9, 'фильм'),
    ('Сияние', 1980, 'Писатель с женой и сыном нанимается на зиму смотрителем пустого горного отеля. Изоляция и тёмное прошлое отеля постепенно сводят его с ума.', 8.4, 'фильм'),
    ('Чужой', 1979, 'Экипаж грузового космического корабля откликается на сигнал с неизвестной планеты и приносит на борт смертельно опасное существо, которое начинает охоту на людей.', 8.5, 'фильм'),
    ('Отступники', 2006, 'Полицейский внедряется в бостонскую мафию, а человек мафии служит в полиции. Каждый из них пытается вычислить «крота» с другой стороны раньше, чем раскроют его самого.', 8.5, 'фильм'),
    ('Ла-Ла Ленд', 2016, 'Начинающая актриса и джазовый пианист влюбляются в Лос-Анджелесе. Они поддерживают мечты друг друга, но успех требует от обоих тяжёлого выбора.', 8.0, 'фильм'),
    ('Отель «Гранд Будапешт»', 2014, 'Легендарный консьерж роскошного европейского отеля и его юный помощник оказываются втянуты в историю с украденной картиной и спором за огромное наследство.', 8.1, 'фильм'),
    ('Общество мёртвых поэтов', 1989, 'Новый учитель литературы в строгой школе для мальчиков учит учеников думать самостоятельно и ценить каждый день, что вызывает недовольство руководства и родителей.', 8.1, 'фильм'),
    ('Умница Уилл Хантинг', 1997, 'Молодой уборщик из Массачусетского технологического института оказывается математическим гением. Психотерапевт помогает ему справиться с травмами прошлого и решить, чего он хочет от жизни.', 8.3, 'фильм'),
    ('Москва слезам не верит', 1979, 'Три подруги приезжают покорять Москву. Спустя двадцать лет одна из них, мать-одиночка и директор комбината, неожиданно встречает свою любовь в электричке.', 8.1, 'фильм'),
    ('Иван Васильевич меняет профессию', 1973, 'Изобретатель создаёт машину времени, и управдом Бунша с вором Жоржем Милославским попадают во времена Ивана Грозного, а сам царь оказывается в московской квартире.', 8.2, 'фильм'),
    ('Брат', 1997, 'Вернувшийся из армии Данила приезжает в Петербург к старшему брату, который оказывается наёмным убийцей. Данила втягивается в бандитские разборки, оставаясь верным своему пониманию справедливости.', 7.9, 'фильм'),
    ('Безумный Макс: Дорога ярости', 2015, 'В постапокалиптической пустыне воительница Фуриоза похищает у тирана его жён и бежит на огромном грузовике. Одиночка Макс становится её невольным союзником в бесконечной погоне.', 8.1, 'фильм'),
    ('Паразиты', 2019, 'Бедная семья хитростью устраивается на работу в дом богачей: сын репетитором, дочь арт-терапевтом, родители водителем и домработницей. Обман постепенно приводит к трагедии.', 8.5, 'фильм'),
    ('Джокер', 2019, 'Одинокий комик-неудачник Артур Флек живёт с больной матерью и страдает от равнодушия общества. Череда унижений превращает его в одного из самых опасных преступников Готэма.', 8.4, 'фильм'),
    ('Ирония судьбы, или С лёгким паром!', 1975, 'В новогоднюю ночь москвич после бани с друзьями по ошибке улетает в Ленинград и попадает в квартиру по такому же адресу, где знакомится с её хозяйкой.', 8.0, 'фильм'),
    ('Гарри Поттер и философский камень', 2001, 'Мальчик-сирота в одиннадцать лет узнаёт, что он волшебник, и поступает в школу магии Хогвартс, где находит друзей и раскрывает тайну спрятанного философского камня.', 7.7, 'фильм'),

    -- Сериалы
    ('Во все тяжкие', 2008, 'Скромный учитель химии узнаёт о смертельной болезни и, чтобы обеспечить семью, начинает варить метамфетамин. Постепенно он превращается в безжалостного наркобарона.', 9.5, 'сериал'),
    ('Игра престолов', 2011, 'Несколько знатных семей борются за Железный трон Семи Королевств, пока на севере пробуждается древняя угроза, о которой все забыли.', 9.2, 'сериал'),
    ('Друзья', 1994, 'Шестеро друзей живут в Нью-Йорке, работают, влюбляются, расстаются и постоянно собираются в любимой кофейне. Сериал о дружбе, которая выдерживает всё.', 8.9, 'сериал'),
    ('Шерлок', 2010, 'Современная версия историй о Шерлоке Холмсе: гениальный и эксцентричный сыщик вместе с военным врачом Джоном Ватсоном раскрывает запутанные преступления в Лондоне.', 9.1, 'сериал'),
    ('Очень странные дела', 2016, 'В маленьком городке пропадает мальчик. Его друзья, мать и местный шериф сталкиваются с секретными опытами, загадочной девочкой и пугающим параллельным миром.', 8.7, 'сериал'),
    ('Офис', 2005, 'Документальная съёмочная группа снимает будни небольшого офиса бумажной компании, где нелепый начальник Майкл Скотт искренне считает себя лучшим другом подчинённых.', 9.0, 'сериал'),
    ('Настоящий детектив', 2014, 'Два детектива из Луизианы расследуют ритуальное убийство. Спустя семнадцать лет их снова допрашивают по этому делу, и становится ясно, что зло так и не остановлено.', 8.9, 'сериал'),
    ('Чернобыль', 2019, 'Мини-сериал о катастрофе на Чернобыльской АЭС в 1986 году: о людях, которые ценой здоровья и жизни ликвидировали последствия аварии, и о попытках скрыть правду.', 9.3, 'сериал'),
    ('Теория большого взрыва', 2007, 'Два гениальных физика, их не менее странные друзья и соседка-официантка пытаются разобраться в отношениях, где научные знания помогают мало.', 8.1, 'сериал'),
    ('Ход королевы', 2020, 'Сирота Бет Хармон в приюте узнаёт шахматы и оказывается невероятно талантливой. Она поднимается на вершину шахматного мира, борясь с одиночеством и зависимостями.', 8.5, 'сериал'),

    -- Мультфильмы
    ('Король Лев', 1994, 'Львёнок Симба после гибели отца, в которой его обвиняет коварный дядя Шрам, убегает из родных земель. Повзрослев, он должен вернуться и занять своё место.', 8.5, 'мультфильм'),
    ('Унесённые призраками', 2001, 'Десятилетняя Тихиро вместе с родителями попадает в мир духов. Родители превращаются в свиней, и девочке приходится работать в волшебной бане, чтобы спасти их.', 8.6, 'мультфильм'),
    ('ВАЛЛ-И', 2008, 'Маленький робот-уборщик много лет в одиночестве собирает мусор на покинутой Земле. Встреча с роботом-исследователем Евой отправляет его в космическое путешествие.', 8.4, 'мультфильм'),
    ('Вверх', 2009, 'Пожилой вдовец привязывает к дому тысячи воздушных шаров, чтобы исполнить мечту покойной жены и улететь в Южную Америку. Случайным попутчиком оказывается мальчик-скаут.', 8.3, 'мультфильм'),
    ('Тайна Коко', 2017, 'Мальчик Мигель мечтает стать музыкантом, хотя в его семье музыка под запретом. В День мёртвых он попадает в мир умерших предков и узнаёт тайну своей семьи.', 8.4, 'мультфильм'),
    ('Головоломка', 2015, 'В голове девочки Райли живут эмоции: Радость, Печаль, Гнев, Страх и Брезгливость. После переезда семьи в новый город в их работе начинается настоящий кавардак.', 8.1, 'мультфильм'),
    ('История игрушек', 1995, 'Игрушки оживают, когда люди не видят. Ковбой Вуди, любимая игрушка мальчика Энди, ревнует его к новому космическому рейнджеру Баззу Лайтеру.', 8.3, 'мультфильм'),
    ('Шрек', 2001, 'Ворчливый огр Шрек, чтобы вернуть себе болото, соглашается освободить принцессу Фиону из замка, охраняемого драконом. Его сопровождает болтливый Осёл.', 7.9, 'мультфильм'),
    ('Мой сосед Тоторо', 1988, 'Две сестры с отцом переезжают в деревню, чтобы быть ближе к больной маме. В лесу рядом с домом они знакомятся с добрым лесным духом Тоторо.', 8.1, 'мультфильм'),
    ('Как приручить дракона', 2010, 'Сын вождя викингов вместо того, чтобы убить дракона, подружился с ним. Эта дружба меняет представления всего племени о драконах.', 8.1, 'мультфильм'),
    ('Зверополис', 2016, 'Крольчиха Джуди становится первой полицейской своего вида в городе зверей. Вместе с хитрым лисом-мошенником она расследует исчезновение хищников.', 8.0, 'мультфильм'),
    ('Ёжик в тумане', 1975, 'Ёжик идёт в гости к Медвежонку считать звёзды, но по дороге теряется в густом тумане, полном загадочных и немного пугающих встреч.', 8.1, 'мультфильм'),
    ('Принцесса Мононоке', 1997, 'Юный принц Аситака, раненный проклятым демоном, отправляется на запад и оказывается в центре войны между людьми, вырубающими лес, и древними духами леса.', 8.3, 'мультфильм')
) AS v(title, release_year, description, rating, type)
JOIN type t ON t.name = v.type;

